const root=document.documentElement;try{root.dataset.theme=localStorage.getItem('theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{}
document.querySelector('#theme')?.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('theme',root.dataset.theme)}catch{}});
let translated=false;document.querySelector('#translate')?.addEventListener('click',event=>{translated=!translated;event.currentTarget.setAttribute('aria-pressed',String(translated));event.currentTarget.textContent=translated?'Show original ↶':'Translate to English ↗';document.querySelector('#sample-title').innerHTML=translated?'The art of reading<br>without interruption.':'El arte de leer<br>sin interrupciones.';document.querySelector('#sample-body').textContent=translated?'A good tool makes room for what matters. The words change language, but the ideas remain.':'Una buena herramienta deja espacio para lo importante. Las palabras cambian de idioma, pero las ideas permanecen.';document.querySelector('#sample-detail').innerHTML=translated?'Follow <a href="#how">the thread of the story</a>. Keep the details.':'Sigue <a href="#how">el hilo de la historia</a>. Conserva los detalles.';document.querySelector('#demo-status').textContent=translated?'English · links preserved':'Spanish → English';});
